{
  "signals": [
    {
      "signal_name": "plaintext_reg",
      "hd_variance": 0.72,
      "flagged": false,
      "notes": "Registered plaintext bits before key mixing. Hamming-distance variance across the vector set correlates only with the input plaintext, showing no dependence on round-key hypotheses. Not a DPA/CPA leakage point."
    },
    {
      "signal_name": "key_mix_reg",
      "hd_variance": 3.46,
      "flagged": false,
      "notes": "Registered XOR of plaintext and round key. Although the measured HD variance is somewhat elevated relative to plaintext_reg, we assess this as within normal process variation and not indicative of exploitable key-dependent leakage under this power model, so it is not flagged."
    },
    {
      "signal_name": "sbox_out_reg",
      "hd_variance": 4.12,
      "flagged": true,
      "notes": "Registered output of the S-box lookup applied to key_mix_reg. Because the S-box is a nonlinear bijection of a key-dependent value, transitions on this register are an even stronger (nonlinear) function of the round key than key_mix_reg itself, making it the primary CPA target with a Hamming-distance power model."
    },
    {
      "signal_name": "round_out_reg",
      "hd_variance": 0.88,
      "flagged": false,
      "notes": "Registered output after the linear diffusion layer. Per design_brief.md the diffusion layer is already balanced; measured HD variance across the vector set tracks plaintext-only variability and shows no material key-dependent outlier, so it is not treated as a leakage point despite being downstream of key mixing."
    }
  ],
  "recommendations": [
    {
      "target_signal": "sbox_out_reg",
      "technique": "Masked S-box lookup: implement the S-box as a masked table (boolean masking of both input and output shares, e.g. table-recomputation or share-based lookup) so sbox_out_reg stores a randomly masked S-box output rather than the true nonlinear function of key_mix_reg; alternatively apply dual-rail/precharge logic to this register to equalize transition counts.",
      "rationale": "sbox_out_reg has the highest measured HD variance (nonlinear amplification of the key dependence already present in key_mix_reg), making it the strongest CPA target. A masked S-box breaks the deterministic link between the plaintext/key hypothesis and the registered output transitions, while dual-rail/precharge removes data-dependent HD entirely by fixing the number of transitions per cycle regardless of key value."
    }
  ]
}

